    pub fn as_mut(&mut self) -> Bound<&mut T> {
        match self {
            ArchivedBound::Included(x) => Bound::Included(x),
            ArchivedBound::Excluded(x) => Bound::Excluded(x),
            ArchivedBound::Unbounded => Bound::Unbounded,
